package com.vandorlabs.physics;

import java.util.*;

/** Independent point-coincidence, active stroke and axis freedom checks. No world ownership. */
public final class CouplerLineConstraintTest {
    private static int checks;
    private static void need(boolean v,String why){checks++;if(!v)throw new AssertionError("Coupler line: "+why);}
    private static void near(double a,double b,String why){need(Math.abs(a-b)<1e-7,why+" "+a+"/"+b);}
    public static void main(String[] args){
        // Two arms + articulated coupler segments along Z allow Z rotation while arms extend/retract.
        for(double parentStroke:new double[]{0,.25,1,3,5})for(double childStroke:new double[]{0,.5,2,4})for(int angle=-75;angle<=75;angle+=5){
            List<CouplerLineConstraint.Anchor> anchors=Arrays.asList(new CouplerLineConstraint.Anchor(0,0,parentStroke,0,0,-childStroke),new CouplerLineConstraint.Anchor(0,0,6+parentStroke,0,0,6-childStroke));CouplerLineConstraint.Result result=CouplerLineConstraint.solve(anchors,RigidTransform.IDENTITY,angle,75);need(result.accepted(),"current stroke accepted");RigidTransform frame=result.transform;near(frame.z,parentStroke+childStroke,"Z translation follows available current strokes");near(frame.x,0,"no invented X translation");near(frame.y,0,"no invented Y translation");double[] point=frame.point(1,0,-childStroke);near(point[0],Math.cos(Math.toRadians(angle)),"free Z rotation X");near(point[1],Math.sin(Math.toRadians(angle)),"free Z rotation Y");near(point[2],parentStroke,"off-axis probe uses current stroke");for(CouplerLineConstraint.Anchor a:anchors){double[] p=frame.point(a.cx,a.cy,a.cz);near(p[0],a.px,"head X");near(p[1],a.py,"head Y");near(p[2],a.pz,"head Z");}
        }
        Random random=new Random(291107);for(int n=0;n<2000;n++){RigidTransform expected=RigidTransform.translation(random.nextDouble()*4,random.nextDouble()*4,random.nextDouble()*4).then(RigidTransform.rotation(random.nextDouble(),random.nextDouble(),random.nextDouble(),random.nextDouble()*360));double[] origin={random.nextDouble(),random.nextDouble(),random.nextDouble()},axis={random.nextDouble()+.1,random.nextDouble()+.1,random.nextDouble()+.1};List<CouplerLineConstraint.Anchor> anchors=new ArrayList<>();for(int i=0;i<4;i++){double x=origin[0]+axis[0]*i,y=origin[1]+axis[1]*i,z=origin[2]+axis[2]*i;double[] p=expected.point(x,y,z);anchors.add(new CouplerLineConstraint.Anchor(p[0],p[1],p[2],x,y,z));}CouplerLineConstraint.Result solved=CouplerLineConstraint.solve(anchors,expected,0,75);need(solved.accepted(),"arbitrary axis/frame accepted");for(int i=0;i<9;i++)near(solved.transform.r[i],expected.r[i],"preferred twist preserved");near(solved.transform.x,expected.x,"translation X");near(solved.transform.y,expected.y,"translation Y");near(solved.transform.z,expected.z,"translation Z");}
        List<CouplerLineConstraint.Anchor> line=Arrays.asList(new CouplerLineConstraint.Anchor(0,0,0,0,0,0),new CouplerLineConstraint.Anchor(0,0,2,0,0,2));need(!CouplerLineConstraint.solve(line,RigidTransform.IDENTITY,75.1,75).accepted(),"twist limit enforced");need(!CouplerLineConstraint.solve(Arrays.asList(line.get(0),new CouplerLineConstraint.Anchor(0,0,3,0,0,2)),RigidTransform.IDENTITY,0,75).accepted(),"unequal current arm spans refuse explicitly");need(!CouplerLineConstraint.solve(Arrays.asList(line.get(0),line.get(1),new CouplerLineConstraint.Anchor(1,0,1,1,0,1)),RigidTransform.IDENTITY,0,75).accepted(),"noncollinear group never silently rigid");need(!CouplerLineConstraint.solve(Arrays.asList(line.get(0),line.get(0)),RigidTransform.IDENTITY,0,75).accepted(),"collapsed group refuses explicitly");need(!CouplerLineConstraint.solve(Arrays.asList(line.get(0),new CouplerLineConstraint.Anchor(Double.NaN,0,2,0,0,2)),RigidTransform.IDENTITY,0,75).accepted(),"nonfinite anchor refuses");need(!CouplerLineConstraint.solve(line,new RigidTransform(new double[]{-1,0,0,0,1,0,0,0,1},0,0,0),0,75).accepted(),"reflected frame refuses");
        for(int sign:new int[]{-1,1}){CouplerLineConstraint.Result opposite=CouplerLineConstraint.solve(Arrays.asList(new CouplerLineConstraint.Anchor(0,0,0,0,0,0),new CouplerLineConstraint.Anchor(0,0,sign*2,0,0,2)),RigidTransform.IDENTITY,10,75);need(opposite.accepted(),"parallel/antiparallel alignment finite");}
        System.out.println("Coupler line constraint PASS checks="+checks+" dynamic strokes/free Z twist/arbitrary axis/preferred frame/explicit refusal; runtime and controls not yet bound");
    }
}
